shell_commands.command:
patch -p1 <<'PATCH'
--- a/tests/src/unit-udt.cpp
+++ b/tests/src/unit-udt.cpp
@@ -20,9 +20,12 @@
     using namespace nlohmann::literals; // NOLINT(google-build-using-namespace)
 #endif

+#include <cstdint>
+#include <limits>
 #include <map>
 #include <memory>
 #include <string>
+#include <type_traits>
 #include <utility>

 namespace udt
@@ -332,6 +335,48 @@
     }
 }

+TEST_CASE_TEMPLATE("enum underlying types" * doctest::test_suite("udt"), T,
+                   std::int8_t, std::uint8_t, std::int16_t, std::uint16_t,
+                   std::int32_t, std::uint32_t, std::int64_t, std::uint64_t)
+{
+    enum class scoped_enum : T {};
+    enum unscoped_enum : T {};
+
+    const T values[] =
+    {
+        (std::numeric_limits<T>::min)(),
+        0,
+        1,
+        static_cast<T>((std::numeric_limits<T>::max)() / 2 + 1),
+        static_cast<T>((std::numeric_limits<T>::max)() - 1),
+        (std::numeric_limits<T>::max)()
+    };
+    const auto expected_type = std::is_unsigned<T>::value
+                               ? json::value_t::number_unsigned
+                               : json::value_t::number_integer;
+
+    for (const auto value : values)
+    {
+        CAPTURE(value);
+        const auto scoped_value = static_cast<scoped_enum>(value);
+        const json scoped_json = scoped_value;
+        CHECK(scoped_json.type() == expected_type);
+        CHECK(scoped_json.template get<T>() == value);
+        CHECK(scoped_json.dump() == std::to_string(value));
+        CHECK(scoped_json.template get<scoped_enum>() == scoped_value);
+
+        const auto unscoped_value = static_cast<unscoped_enum>(value);
+        json unscoped_json = "old value";
+        nlohmann::to_json(unscoped_json, unscoped_value);
+        CHECK(unscoped_json.type() == expected_type);
+        CHECK(unscoped_json.template get<T>() == value);
+        CHECK(unscoped_json.dump() == std::to_string(value));
+        CHECK(unscoped_json.template get<unscoped_enum>() == unscoped_value);
+    }
+}
+
 namespace udt
 {
 struct legacy_type
PATCH
cd /testbed/build && cmake .. > /tmp/json-enum-cmake.log && make test-udt_cpp11 > /tmp/json-enum-build.log 2>&1 && ./tests/test-udt_cpp11 --test-case='enum underlying types*' > /tmp/json-enum-before.log 2>&1; result=$?; tail -25 /tmp/json-enum-before.log; exit "$result"

python3 - <<'PY'
from pathlib import Path
path = Path('tests/src/unit-udt.cpp')
text = path.read_text()
anchor = 'namespace udt\n{\nstruct legacy_type\n'
assert text.count(anchor) == 1
addition = '''TEST_CASE_TEMPLATE("enum underlying types" * doctest::test_suite("udt"), T,
                   std::int8_t, std::uint8_t, std::int16_t, std::uint16_t,
                   std::int32_t, std::uint32_t, std::int64_t, std::uint64_t)
{
    enum class scoped_enum : T {};
    enum unscoped_enum : T {};

    const T values[] =
    {
        (std::numeric_limits<T>::min)(),
        0,
        1,
        static_cast<T>((std::numeric_limits<T>::max)() / 2 + 1),
        static_cast<T>((std::numeric_limits<T>::max)() - 1),
        (std::numeric_limits<T>::max)()
    };
    const auto expected_type = std::is_unsigned<T>::value
                               ? json::value_t::number_unsigned
                               : json::value_t::number_integer;

    for (const auto value : values)
    {
        CAPTURE(value);
        const auto scoped_value = static_cast<scoped_enum>(value);
        const json scoped_json = scoped_value;
        CHECK(scoped_json.type() == expected_type);
        CHECK(scoped_json.template get<T>() == value);
        CHECK(scoped_json.dump() == std::to_string(value));
        CHECK(scoped_json.template get<scoped_enum>() == scoped_value);

        const auto unscoped_value = static_cast<unscoped_enum>(value);
        json unscoped_json = "old value";
        nlohmann::to_json(unscoped_json, unscoped_value);
        CHECK(unscoped_json.type() == expected_type);
        CHECK(unscoped_json.template get<T>() == value);
        CHECK(unscoped_json.dump() == std::to_string(value));
        CHECK(unscoped_json.template get<unscoped_enum>() == unscoped_value);
    }
}

'''
path.write_text(text.replace(anchor, addition + anchor))
PY
cd /testbed/build && make test-udt_cpp11 > /tmp/json-enum-build.log 2>&1 && ./tests/test-udt_cpp11 --test-case='enum underlying types*' > /tmp/json-enum-before.log 2>&1; result=$?; tail -35 /tmp/json-enum-before.log; if [ "$result" -ne 0 ]; then tail -5 /tmp/json-enum-build.log; fi; exit "$result"

